package com.shazwan.idash3;
import org.json.*;import java.net.*;import java.io.*;import java.util.*;import javax.crypto.*;import javax.crypto.spec.SecretKeySpec;
final class BitChordCatalogue implements AutoCloseable {
 volatile boolean closed;volatile HttpURLConnection request;
 static String endpoint(String call,String key,String value)throws Exception{return "https://www.jiosaavn.com/api.php?__call="+call+"&_format=json&_marker=0&api_version=4&ctx=android&p=1&n=20&"+key+"="+java.net.URLEncoder.encode(value,"UTF-8");}
 String get(String address)throws Exception{if(closed)throw new IOException("Cancelled");HttpURLConnection c=(HttpURLConnection)new URL(address).openConnection();request=c;try{c.setConnectTimeout(5000);c.setReadTimeout(7000);c.setRequestProperty("Accept","application/json");c.setRequestProperty("User-Agent","Mozilla/5.0 iDash-NativeMusic/1");if(c.getResponseCode()!=200)throw new IOException("Katalog HTTP "+c.getResponseCode());try(InputStream in=c.getInputStream();ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] b=new byte[4096];int n;while((n=in.read(b))!=-1){if(closed||Thread.currentThread().isInterrupted())throw new IOException("Cancelled");if(out.size()+n>1024*1024)throw new IOException("Katalog terlalu besar");out.write(b,0,n);}return new String(out.toByteArray(),"UTF-8");}}finally{c.disconnect();if(request==c)request=null;}}
 static String plain(String s){return android.text.Html.fromHtml(s,android.text.Html.FROM_HTML_MODE_LEGACY).toString();}
 static List<MusicTrack> parse(String body)throws Exception{JSONArray rows=new JSONObject(body).optJSONArray("results");List<MusicTrack> result=new ArrayList<>();if(rows==null)return result;for(int i=0;i<Math.min(20,rows.length());i++){JSONObject row=rows.optJSONObject(i);if(row==null)continue;JSONObject more=row.optJSONObject("more_info");String artist="";if(more!=null){JSONObject map=more.optJSONObject("artistMap");JSONArray names=map==null?null:map.optJSONArray("primary_artists");if(names!=null)for(int j=0;j<Math.min(4,names.length());j++){JSONObject name=names.optJSONObject(j);if(name!=null)artist+=(artist.isEmpty()?"":", ")+plain(name.optString("name"));}}String id=row.optString("id");if(!id.isEmpty())result.add(new MusicTrack(id,plain(row.optString("title","Untitled")),artist,more==null?"":plain(more.optString("album")),"",false));}return result;}
 List<MusicTrack> search(String query)throws Exception{return parse(get(endpoint("search.getResults","q",query)));}
 static String decode(String encoded)throws Exception{Cipher cipher=Cipher.getInstance("DES/ECB/PKCS5Padding");cipher.init(Cipher.DECRYPT_MODE,new SecretKeySpec("38346591".getBytes("UTF-8"),"DES"));String url=new String(cipher.doFinal(java.util.Base64.getDecoder().decode(encoded)),"UTF-8").trim();URI u=new URI(url);if(!"https".equalsIgnoreCase(u.getScheme())||u.getHost()==null||u.getUserInfo()!=null)throw new IOException("URL audio tidak sah");return url;}
 String resolve(MusicTrack t)throws Exception{if(t.local)return t.location;JSONObject root=new JSONObject(get(endpoint("song.getDetails","pids",t.id)));JSONObject song=null;JSONArray songs=root.optJSONArray("songs");if(songs!=null)song=songs.optJSONObject(0);if(song==null){Iterator<String> it=root.keys();while(it.hasNext()&&song==null)song=root.optJSONObject(it.next());}JSONObject more=song==null?null:song.optJSONObject("more_info");if(more==null)throw new IOException("Audio tidak tersedia");return decode(more.optString("encrypted_media_url"));}
 public void close(){closed=true;HttpURLConnection c=request;if(c!=null)c.disconnect();}
}
